// The board has no context bar on this screen: context null hides it (core/shell.js).
holdReady();
mountShell({ screen: "compare", context: null, onLang: draw });
const doc = await loadSites();
interface Scenario { stereo_x_m: number; stereo_y_m: number; n?: string | number }
const chosenWindows = classroomWindows(doc.sites, location.hash, getState());
const scenarios = chosenWindows.map(s => s.site) as unknown as Scenario[];
interface Grid { nx: number; ny: number; dx: number; x0: number; y0: number; data: ArrayLike<number> }
const grid = (await loadRegion()) as Grid;
await mountTerrain(document.getElementById("terrain")!, { sites: doc.sites.map((s) => { const letters = chosenWindows.flatMap((w, i) => w.site.id === s.id ? [String.fromCharCode(65 + i)] : []).join("/"); return letters ? { ...s, n: letters } : s; }), selected: getState().site, labels: false });

type Switch = "allowSite" | "allowDate" | "allowProof" | "allowRules" | "allowLab";
type Layer3 = "answer" | "why" | "proof";
const cfg: { step: number; device: string; openLayer: Layer3 } & Record<Switch, boolean> = {
  step: 1,
  device: "laptop",
  openLayer: "why",
  allowSite: true,
  allowDate: false,
  allowProof: false,
  allowRules: false,
  allowLab: true
};
const PresentIcon = () => <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="2.5" y="1.5" width="11" height="13" rx="2" /><path d="M5.5 11V8.5M8 11V5.5M10.5 11V7.5" stroke-linecap="round" /></svg>;
const LAYERS: [Layer3, string][] = [["answer", "act.l1"], ["why", "act.l2"], ["proof", "act.l3"]];

/** Drops the previous tree first, so every pass builds fresh nodes (as the old innerHTML did: focus is restored by data-focus). */
function paint(vnode: preact.ComponentChild, host: HTMLElement) { mount(null, host); host.replaceChildren(); mount(vnode, host); }
const $ = (id: string) => document.getElementById(id) as HTMLElement;

// location.href keeps the scenario (site, start, rules…) and the activity switches ride on the query string.
function shareUrl() {
  const u = new URL(hrefTo("present.html"), location.href);
  u.searchParams.set("layer", cfg.openLayer);
  u.searchParams.set("allowSite", cfg.allowSite ? "1" : "0");
  u.searchParams.set("allowDate", cfg.allowDate ? "1" : "0");
  u.searchParams.set("allowProof", cfg.allowProof ? "1" : "0");
  u.searchParams.set("allowRules", cfg.allowRules ? "1" : "0");
  u.searchParams.set("allowLab", cfg.allowLab ? "1" : "0");
    u.hash = buildHash({ sc: chosenWindows.map(w => ({ ...w, site: w.site.id })) });
  return u.toString();
}

/** Hillshade of the real LOLA grid fitted to the scenarios, drawn once per size; markers use the same transform. */
const reliefCache: { key: string; canvas: HTMLCanvasElement | null } = { key: "", canvas: null };
function hAt(i: number, j: number) {
  const a = Math.floor(i), b = Math.floor(j);
  if (a < 0 || b < 0 || a >= grid.nx - 1 || b >= grid.ny - 1) return NaN;
  const u = i - a, v = j - b, d = grid.data, n = grid.nx, q = b * n + a;
  return (d[q] * (1 - u) + d[q + 1] * u) * (1 - v) + (d[q + n] * (1 - u) + d[q + n + 1] * u) * v;
}
function paintPreviewTerrain(frame: HTMLElement) {
  const W = frame.clientWidth, H = frame.clientHeight;
  if (!W || !H || !scenarios.length) return;
  const xs = scenarios.map((s) => s.stereo_x_m), ys = scenarios.map((s) => s.stereo_y_m);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  // usable area keeps markers clear of the badge (top) and the question glass (bottom)
  const pad = 40, top = 48, bot = H - 100;
  const mpp = Math.max((x1 - x0) / (W - 2 * pad), (y1 - y0) / (bot - top), grid.dx / 4);
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, py = (top + bot) / 2;
  const dpr = Math.min(2, devicePixelRatio || 1), w = Math.round(W * dpr), h = Math.round(H * dpr);
  const key = [w, h, mpp.toFixed(2), cx.toFixed(0), cy.toFixed(0)].join();
  if (reliefCache.key !== key) {
    const cv = document.createElement("canvas"); cv.width = w; cv.height = h;
    const img = new ImageData(w, h), px = img.data, e = 0.5, m = mpp / dpr;
    for (let r = 0; r < h; r++) for (let c = 0; c < w; c++) {
      const x = cx + (c - w / 2) * m, y = cy - (r - py * dpr) * m, fi = (x - grid.x0) / grid.dx, fj = (y - grid.y0) / grid.dx, p = (r * w + c) * 4;
      const hx = (hAt(fi + e, fj) - hAt(fi - e, fj)) / (2 * e * grid.dx), hy = (hAt(fi, fj + e) - hAt(fi, fj - e)) / (2 * e * grid.dx);
      const v = Number.isFinite(hx + hy) ? shadeValue(hx, hy) : 7;
      px[p] = v; px[p + 1] = v + 2; px[p + 2] = v + 7; px[p + 3] = 255;
    }
    cv.getContext("2d")!.putImageData(img, 0, 0);
    reliefCache.key = key; reliefCache.canvas = cv;
  }
  const host = frame.querySelector(".mp-pv-map") as HTMLElement;
  const cv = document.createElement("canvas"); cv.width = w; cv.height = h; cv.setAttribute("aria-hidden", "true");
  cv.getContext("2d")!.drawImage(reliefCache.canvas!, 0, 0);
  host.replaceChildren(cv, ...scenarios.map((s) => {
    const mk = document.createElement("span"); mk.className = "mp-pv-marker"; mk.textContent = String.fromCharCode(65 + scenarios.indexOf(s)); mk.setAttribute("aria-hidden", "true");
    mk.style.left = W / 2 + (s.stereo_x_m - cx) / mpp + "px"; mk.style.top = py - (s.stereo_y_m - cy) / mpp + "px";
    return mk;
  }));
}

function draw() {
  // The Class Kit reuses Compare navigation, but keeps its own localized tab title.
  document.title = "MoonProof · " + t("act.kit");
  const focusKey = (document.activeElement as HTMLElement | null)?.dataset?.focus;
  const startDate = (getState().start || "2027-03-14T06:00:00Z").slice(0, 10);
  const steps: [number, string, string][] = [
    [1, t("act.s1"), t("act.s1d")],
    [2, t("act.s2"), t("act.s2d")],
    [3, t("act.s3"), t("act.s3d")],
    [4, t("act.s4"), t("act.s4d")]
  ];
  const tip = /^([^:]+:)([\s\S]*)$/.exec(t("act.tip"));
  paint(<>
    <div><span class="mp-act-kicker">{t("act.kit")}</span><h1 class="mp-act-h1">{t("act.title")}</h1></div>
    {steps.map(([n, title, sub]) => (
      <button class={`mp-step-item ${n < cfg.step ? "is-done" : n === cfg.step ? "is-active" : ""}`} data-step={n} data-focus={`step${n}`} type="button" aria-current={n === cfg.step ? "step" : undefined} onClick={() => { cfg.step = n; draw(); setTimeout(() => document.getElementById(({ 1: "act-preview", 2: "act-controls", 3: "btn-present", 4: "act-share" } as Record<number, string>)[n])?.scrollIntoView({ behavior: "smooth", block: "nearest" }), 0); }}>
        <span class="mp-step-num">{n < cfg.step ? "✓" : n}</span>
        <span class="mp-step-txt"><strong>{title}</strong><span>{sub}</span></span>
      </button>
    ))}
    <p class="mp-act-tip">{tip ? <><b>{tip[1]}</b>{tip[2]}</> : t("act.tip")}</p>
  </>, $("act-steps"));

  const prevEl = $("act-preview");
  const openIdx = LAYERS.findIndex(([k]) => k === cfg.openLayer);
  const setLayer = (k: Layer3) => { cfg.openLayer = k; setState({ layer: k }); draw(); };
  paint(<>
    <div class="mp-act-head">
      <h2>{t("act.previewTitle")}</h2>
      <div class="mp-chip-row">
        <button class={`mp-chip ${cfg.device === "laptop" ? "is-active" : ""}`} data-dev="laptop" data-focus="dev-laptop" type="button" aria-pressed={cfg.device === "laptop"} onClick={() => { cfg.device = "laptop"; draw(); }}>{t("act.laptop")}</button>
        <button class={`mp-chip ${cfg.device === "mobile" ? "is-active" : ""}`} data-dev="mobile" data-focus="dev-mobile" type="button" aria-pressed={cfg.device === "mobile"} onClick={() => { cfg.device = "mobile"; draw(); }}>{t("act.mobile")}</button>
      </div>
    </div>
    <div class={`mp-preview-frame ${cfg.device === "mobile" ? "is-mobile" : ""}`}>
      <div class="mp-pv-map"></div>
      <span class="mp-pv-badge">{t("act.badge")}</span>
      <span id="prev-seal" class="mp-pv-seal"></span>
      <div class="mp-pv-q mp-glass">
        <strong>{t("act.prompt")}</strong>
        <span>{t("act.promptSub")}</span>
        <span class="mp-pv-layer-note">{t("act.previewLayer." + cfg.openLayer)}</span>
      </div>
    </div>
    <div class="mp-act-head mp-act-open">
      <span>{t("act.openIn")}</span>
      <div class="mp-chip-row mp-layer-tabs" role="tablist" aria-label={t("act.layers")}>
        {LAYERS.map(([k, label], i) => (
          <button role="tab" class={`mp-layer-tab ${i < openIdx ? "is-open" : ""} ${k === cfg.openLayer ? "is-active" : ""}`} data-layer={k} data-focus={`layer-${k}`} type="button" aria-selected={k === cfg.openLayer} tabIndex={k === cfg.openLayer ? 0 : -1}
            onClick={() => setLayer(k)}
            onKeyDown={(ev: KeyboardEvent) => {
              const d = ev.key === "ArrowRight" ? 1 : ev.key === "ArrowLeft" ? -1 : 0;
              if (!d) return;
              ev.preventDefault();
              setLayer(LAYERS[(LAYERS.findIndex(([x]) => x === cfg.openLayer) + d + LAYERS.length) % LAYERS.length][0]);
            }}>{t(label)}</button>
        ))}
      </div>
    </div>
  </>, prevEl);
  // Imperative on purpose: the seal and the relief canvas are core-built nodes that paintPreviewTerrain also redraws on resize.
  (prevEl.querySelector("#prev-seal") as HTMLElement).appendChild(sealEl(sealFor(doc.status)));
  paintPreviewTerrain(prevEl.querySelector(".mp-preview-frame") as HTMLElement);

  const vars = { date: startDate, night: DEFAULT_RULES.night, blackout: DEFAULT_RULES.blackout };
  const toggles: [Switch, string, string][] = [
    ["allowSite", "act.tSite", "act.tSiteD"],
    ["allowDate", "act.tDate", "act.tDateD"],
    ["allowProof", "act.tProof", "act.tProofD"],
    ["allowRules", "act.tRules", "act.tRulesD"],
    ["allowLab", "act.tLab", "act.tLabD"]
  ];
  paint(<>
    <div class="mp-act-head"><h2>{t("act.ctrlTitle")}</h2><span class="mp-act-students">{t("act.students")}</span></div>
    {toggles.map(([k, label, sub]) => (
      <label class="mp-toggle-row">
        <span class="mp-toggle-txt"><span>{t(label)}</span><small>{t(sub, vars)}</small></span>
        <button class={`mp-switch ${cfg[k] ? "is-on" : ""}`} data-toggle={k} data-focus={`sw-${k}`} type="button" role="switch" aria-checked={cfg[k]} onClick={() => { cfg[k] = !cfg[k]; draw(); }}></button>
      </label>
    ))}
    <p class="mp-act-suggest">{t("act.suggest")}</p>
    <div class="mp-teacher-notes">
      <strong>{t("act.notesTitle").split(" · ")[0]}<span class="mp-muted">{" · " + (t("act.notesTitle").split(" · ")[1] ?? "")}</span></strong>
      <p>{t("act.notesBody")}</p>
      <p>{t("act.notesBody2")}</p>
    </div>
  </>, $("act-controls"));

  const url = shareUrl();
  let qr = "";
  try { qr = qrSvg(url, { label: t("act.qrLabel") }); } catch { qr = ""; } // too long for a QR: omit it, the link stays
  paint(<>
    {qr ? <div class="mp-qr" dangerouslySetInnerHTML={{ __html: qr }} /> : null}
    <div class="mp-share-main">
      <strong>{t("act.shareTitle")}</strong>
      <div class="mp-share-url" id="share-url">{url}</div>
      <div class="mp-share-note">{t("act.access")}</div>
    </div>
    <div class="mp-chip-row mp-share-btns">
      <button id="btn-copy" class="mp-btn-outline" data-focus="copy" type="button" onClick={async (e: MouseEvent) => {
        const btn = e.currentTarget as HTMLElement;
        try {
          if (!navigator.clipboard?.writeText) throw new Error("Clipboard unavailable");
          await navigator.clipboard.writeText(url);
          btn.textContent = t("act.copied");
        } catch { btn.textContent = t("act.copyError"); }
      }}>{t("act.copy")}</button>
      <a class="mp-btn-jade" id="btn-present" href={url}><PresentIcon />{t("act.present")}</a>
    </div>
  </>, $("act-share"));

  if (focusKey) (document.querySelector(`[data-focus="${focusKey}"]`) as HTMLElement | null)?.focus();
}

addEventListener("resize", () => { const f = document.querySelector(".mp-preview-frame"); if (f) paintPreviewTerrain(f as HTMLElement); });
draw();
markReady();
